/// The cities whose zones the app downloads (docs/city-zone-downloads.md), as data/city-zones.json had them when
/// the app was built, and the cities whose zones are built in.
extension CityZoneDownloads {
    static let builtIn: [CityZoneDownload] = [
        CityZoneDownload(
            id: "berlin", place: "Berlin", authority: "Land Berlin",
            timeZone: "Europe/Berlin", source: URL(string: "https://www.berlin.de/sen/uvk/mobilitaet-und-verkehr/verkehrsplanung/elektromobilitaet/elektro-tretroller/")!,
            bounds: GeoBounds(south: 52.338246, west: 13.088352, north: 52.675456, east: 13.761155)
        ),
        CityZoneDownload(
            id: "hamburg", place: "Hamburg", authority: "Freie und Hansestadt Hamburg, Behörde für Verkehr und Mobilitätswende, DL-DE BY 2.0",
            timeZone: "Europe/Berlin", source: URL(string: "https://www.hamburg.de/verkehr/e-mobilitaet/e-scooter-411320")!,
            bounds: GeoBounds(south: 53.395086, west: 9.730131, north: 53.739437, east: 10.325137)
        ),
    ]

    static let builtInCities: Set<String> = ["alexandria", "antwerpen", "arlington", "arlingtoncemetery", "atlanta", "baltimore", "basel", "bergen", "boise", "bordeaux", "boulder", "braunschweig", "cityoflondon", "columbus", "helsinki", "jarvenpaa", "lambeth", "minneapolis", "munchen", "munster", "namur", "newyork", "norfolk", "norrkoping", "omaha", "oslo", "ottawa", "oygarden", "porto", "poznan", "reykjavik", "riga", "rostock", "sacramento", "santamonica", "seattle", "stalbert", "stockholm", "taupo", "trondheim", "turku", "vaasa", "vancouver", "vantaa", "vasteras", "washington", "wien", "zurich"]
}

